def profile(r):
    kind = r['illustration']
    return PROFILES['food' if kind in ('chicken', 'taproom') else kind]


def expanded_service(r, index):
    return r['services'][index]['body'] + ' ' + profile(r)['service'][index]


def paragraphs(*texts):
    return ''.join('<p>'+e(t)+'</p>' for t in texts if t)


def render(r):
    p = profile(r)
    titles = list(p['story'])
    if r['slug'] == 'lower-merion-pediatric-dentistry':
        titles = ['A small smile. A whole new experience.', 'Make room for every little question.', 'A first visit, with a little familiarity.']
    if r['slug'] == 'pet-dermatology-center':
        titles = ['A closer look at skin and ears.', 'The details you notice matter.', 'Bring your questions into the conversation.']
    if r['slug'] == 'paws-spay-neuter-wellness-clinic':
        titles = ['Care starts with access.', 'Find the right route for your pet.', 'A scheduled visit. A clear next step.']
    closing = {
        'insurance': 'If your enquiry brings several questions together, write down which one matters most today. Ask the agency how it would like to receive supporting information, and keep personal documents within its own approved contact channels.',
        'home': 'A property conversation does not have to cover everything at once. Begin with the decision in front of you, whether that is exploring an area, discussing a property or preparing to sell. Keep the next action connected to that decision.',
        'dental': 'There may be practical questions alongside the reason for your appointment. Make room to ask about the office, the information you need and how to follow up after the initial enquiry. A clear next step helps you plan the visit.',
        'pet': 'There may be practical questions alongside the reason for the visit. Ask about the appointment route and how to share information with the team. Keeping those details together can make it easier to plan the visit you have arranged.',
        'hvac': 'If you are comparing a planned project with work on an existing system, say so when you enquire. Ask the company to explain the next stage of the conversation and the information it needs to discuss your particular property.',
        'gym': 'You can be curious without having your whole training routine worked out. Pick the programme you want to explore and ask the questions that matter for your first session. The next step is the one you arrange with the academy.',
        'auto': 'A shortlist is a starting point, not a commitment. Keep the questions you want to ask about each vehicle together, and confirm which ones are available to view. Let the dealership know what you hope to cover during your visit.',
        'auto_service': 'If you have more than one item to discuss, mention that when you enquire about an appointment. Ask how the shop would like the information provided and how it will keep you informed about the work you are discussing.',
        'food': 'Sometimes the details are as simple as choosing where to collect an order. Sometimes there is a group or an occasion to think about. Use the restaurant’s own route to confirm the plan and ask anything that still needs an answer.'
    }
    key = 'food' if r['illustration'] in ('chicken','taproom') else r['illustration']
    copy = [(r['about'], p['intro']), (NOTES[r['slug']], p['middle']), (p['end'], closing[key])]
    chapters = []
    for i, (heading, texts) in enumerate(zip(titles, copy)):
        drawing = art.svg(r['illustration'], i, 'Dimensional '+r['illustration'].replace('_', ' ')+' illustration: '+heading)
        chapters.append('<section class="long-chapter chapter-'+str(i)+'" aria-labelledby="chapter-title-'+str(i)+'"><div class="container chapter-layout"><div class="chapter-copy"><h2 id="chapter-title-'+str(i)+'">'+e(heading)+'</h2>'+paragraphs(*texts)+'<a class="text-action" href="'+e(r['cta_url'])+'">'+e(r['cta_label'])+'<svg class="action-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a></div><figure class="chapter-art">'+drawing+'</figure></div></section>')
    guide_rows = ''.join('<article class="consideration"><h3>'+e(t)+'</h3><p>'+e(b)+'</p></article>' for t,b in p['guide'][1])
    guide = '<section class="conversation-section" aria-labelledby="conversation-title"><div class="container conversation-layout"><div><h2 id="conversation-title">'+e(p['guide'][0])+'</h2><p class="conversation-intro">Some questions are about the bigger picture. Others are about the practical details. Give both a little room before getting in touch with '+e(r['name'])+'. A clear starting point leaves more space for the conversation you actually want to have.</p></div><div class="considerations">'+guide_rows+'</div></div></section>'
    steps = ''.join('<li><div class="step-heading">'+service_icons.svg(icon, r['illustration'])+'<h3>'+e(t)+'</h3></div><p>'+e(b)+'</p></li>' for (t,b),icon in zip(p['steps'],['resources','diagnostics','appointments']))
    journey = '<section class="next-steps" id="next-step" aria-labelledby="next-title"><div class="container"><div class="next-intro"><h2 id="next-title">A little preparation.<br>A clearer next step.</h2><p>There is room to explore before you decide. Start with the part that interests you, take your questions with you and connect directly with '+e(r['name'])+' when you are ready.</p></div><ol class="journey-list">'+steps+'</ol><a class="btn btn-warning" href="'+e(r['cta_url'])+'">'+e(r['cta_label'])+'</a></div></section>'
    faq = list(p['faq'])
    if r['slug'] == 'paws-spay-neuter-wellness-clinic':
        faq[2] = ('Is this an emergency hospital?', 'No. The PAWS Grays Ferry clinic states that it is not an emergency hospital and does not provide overnight care. Its listed services use scheduled appointments; check the clinic website for the appropriate service and scheduling guidance.')
    if r['slug'] == 'pet-dermatology-center':
        faq[2] = ('What is the practice focused on?', 'Pet Dermatology Center focuses on skin and ear diseases. Its listed services include allergy testing, skin biopsy, electrocautery and fluorescent light energy therapy. Contact the practice to discuss an individual enquiry and the appropriate appointment.')
    if r['slug'] == 'lower-merion-pediatric-dentistry':
        faq[0] = ('Where can parents prepare for a first visit?', 'The practice website has first-visit information and parent resources. Explore those materials, then contact the Ardmore office with your child’s age and the questions you want to discuss before arranging an appointment.')
    questions = ''.join('<details'+(' open' if i == 0 else '')+'><summary>'+e(q)+'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14"/><path class="question-stem" d="M12 5v14"/></svg></summary><div>'+paragraphs(a)+'</div></details>' for i,(q,a) in enumerate(faq))
    answers = '<section class="long-faq" id="questions" aria-labelledby="faq-title"><div class="container faq-layout"><div><h2 id="faq-title">Before you<br>take the next step.</h2><p>A few useful starting points. For current appointments, availability and individual questions, connect with '+e(r['name'])+' through its own website.</p></div><div class="questions-list">'+questions+'</div></div></section>'
    return ''.join(chapters[:2]) + guide + chapters[2] + journey + answers
